  "isoDate": "2026-08-10T15:12:17",
  "sourceUrl": "https://www.idx.co.id/StaticData/NewsAndAnnouncement/ANNOUNCEMENTSTOCK/From_EREP/202608/936aa46c3f_b6c001f7ef.pdf",
  "sourceLabel": "IDX",
